def max_product(nums):
    """
    Returns the maximum product of any two distinct elements in the list.
    """
    if len(nums) < 2:
        raise ValueError("The list must contain at least two elements.")

    # Initialize the two largest and two smallest values
    max1 = max2 = float('-inf')
    min1 = min2 = float('inf')

    for num in nums:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    return max(max1 * max2, min1 * min2)

