def length_of_longest_subsequence(arr):
    """
    Return the length of the longest subsequence where each element is distinct
    and followed by the next different element in the original array.
    """
    if not arr:
        return 0

    longest_subsequence = []
    seen_elements = set()

    for element in arr:
        if element not in seen_elements:
            longest_subsequence.append(element)
            seen_elements.add(element)

    return len(longest_subsequence)

