def longest_distinct_subsequence(arr):
    """
    Returns the length of the longest subsequence of arr where each element
    in the subsequence is distinct and followed by the next different element
    in the original array.
    """
    if not arr:
        return 0

    distinct_elements = set()
    longest_length = 0
    current_length = 0

    for element in arr:
        if element not in distinct_elements:
            distinct_elements.add(element)
            current_length += 1
            longest_length = max(longest_length, current_length)
        else:
            current_length = 1
            distinct_elements = {element}

    return longest_length

